//! 🧪️ Declared finite LIST carriers retain actual ordered words through original central receiving.
use super::*;
fn contract()->serde_json::Value{serde_json::from_str(include_str!("🧪️tests/type-list-input.json")).unwrap()}
#[test]
fn original_cardinality_choice_plan_refuses_prior_preserve_layout_and_admits_replace(){
 use semio_framework_plugin::action_staging::*;
 let token=StagedFormToken{action:editing::SET_SNAPSHOT_VALUE_ACTION_ID.into(),window:"list-original".into(),generation:"1".into(),revision:"0".repeat(64)};let status=StagedFormStatus{token:token.clone(),ready:false,diagnostics:Vec::new(),diagnostic_offset:"0".into(),diagnostic_total:"0".into()};let mut binding=StagedFormBinding{token,layout:StagedFormLayout::Preserve,edits:vec![StagedFormBindingEdit::Choice{kind:StagedFormChoiceEditKind::Set,path:vec!["value".into(),"$ifcInputs".into(),"0".into(),"value".into()],options:vec![StagedFormBindingOption{key:"0".into(),value:DslValue::Object(vec![("kind".into(),DslValue::String("aggregate".into())),("value".into(),DslValue::Array(Vec::new()))])}]}]};let input=DslValue::String("0".into());assert!(binding.plan(&status,Some(&input)).is_err());binding.layout=StagedFormLayout::Replace;assert!(binding.plan(&status,Some(&input)).is_ok());
}
fn source(law:&serde_json::Value,name:&str)->Arc<IfcSnapshot>{let domain=law["domains"].as_array().unwrap().iter().find(|row|row["entity"]==name).unwrap();Arc::new(IfcSnapshot{entities:vec![IfcEntity{id:1,name:name.into(),args:vec![IfcValue::Unset],complex:domain["ancestors"].as_array().unwrap().iter().map(|name|IfcComplexType{name:name.as_str().unwrap().into(),args:Vec::new()}).collect()}],..Default::default()})}
fn event(row:&serde_json::Value)->editing::SnapshotEditEvent{editing::SnapshotEditEvent::SetValue{path:"/entities/0".into(),value:super::type_input_tests::raw(&serde_json::json!({"$ifcType":row["entity"],"$ifcInputs":[{"index":"0","value":{"kind":"aggregate","value":row["words"].as_array().unwrap().iter().map(|bits|serde_json::json!({"kind":"real","value":{"bits":bits}})).collect::<Vec<_>>()}}]}))}}
#[test]
fn original_finite_real_lists_use_exact_central_mutation_inverse_and_issued_rules(){
 if DetailsTestProfile::catalog().schema!="IFC4X3_ADD2"{return;}
 let law=contract();for row in law["cases"].as_array().unwrap(){let snapshot=source(&law,row["entity"].as_str().unwrap());let mut caller=OriginalWorkFixture::new();let mut work=Work::new(editing::SET_SNAPSHOT_VALUE_ACTION_ID);
  inputs(&snapshot,event(row),&mut caller,&mut work,|input,caller,work|{let mut output=None;for turn in 0..1000000{match caller.work_turn(grant(),1,|cx|work.step(input,cx)){Ok(ArtifactCommandWorkStep::Complete(emit))=>{output=Some(Ok(emit));break;},Err(error)=>{output=Some(Err(error));break;},_=>{}}assert!(turn<999999);}let output=output.unwrap();assert_eq!(output.is_ok(),row["admitted"].as_bool().unwrap(),"{}",row["id"]);
   if let Ok(emit)=output{assert_eq!(emit.artifact_mutations.len(),1);assert!(matches!(emit.artifact_mutations[0],IfcMutation::SetEntityArg(_)));let mutation=&emit.artifact_mutations[0];let inverse=mutation.inverse(&snapshot).unwrap();let mut next=protocol::apply_diff_cold(mutation.diff(&snapshot).diff(),&snapshot).unwrap();let expected=IfcValue::Aggregate(row["words"].as_array().unwrap().iter().map(|word|IfcValue::Real(f64::from_bits(word.as_str().unwrap().parse().unwrap()))).collect());assert!(ifc_arguments_identical(&next.entities[0].args,&[expected]));for mutation in inverse{next=protocol::apply_diff_cold(mutation.diff(&next).diff(),&next).unwrap();}assert!(ifc_arguments_identical(&next.entities[0].args,&snapshot.entities[0].args));assert!(ifc_complex_identical(&next.entities[0].complex,&snapshot.entities[0].complex));}
   super::constituent_optional_shape_tests::close_with_denials(caller,work);assert!(work.terminal_is_empty());});caller.finish();}
}
#[test]
fn original_list_receiving_denies_each_axis_before_child_shape_or_value_progress(){
 if DetailsTestProfile::catalog().schema!="IFC4X3_ADD2"{return;}
 let law=contract();let row=law["cases"].as_array().unwrap().iter().find(|row|row["id"]=="point-three-exact").unwrap();let snapshot=source(&law,row["entity"].as_str().unwrap());let mut caller=OriginalWorkFixture::new();let mut work=Work::new(editing::SET_SNAPSHOT_VALUE_ACTION_ID);
 inputs(&snapshot,event(row),&mut caller,&mut work,|input,caller,work|{let mut reached=false;for _ in 0..1000000{if work.constituent_roster.receiving_primitives(){reached=true;let demand=work.work_demands(input,4096).unwrap();for axis in 0..6{let mut denied=grant();let mut fuel=1;match axis{0=>denied.maximum_items=0,1 if demand.copy_bytes>0=>denied.maximum_copy_bytes=demand.copy_bytes-1,2 if demand.capacity_bytes>0=>denied.maximum_capacity_bytes=demand.capacity_bytes-1,3 if demand.release_bytes>0=>denied.maximum_release_bytes=demand.release_bytes-1,4=>denied.maximum_depth=0,5=>fuel=0,_=>continue};let state=work.constituent_roster.metadata();caller.work_turn(denied,fuel,|cx|{let before=cx.retained_progress();let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||work.step(input,cx));assert!(!matches!(answer?,ArtifactCommandWorkStep::Complete(_)));assert_eq!(before,cx.retained_progress());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));Ok(())}).unwrap();assert_eq!(state,work.constituent_roster.metadata());}}
  if work.domain_validated{break;}assert!(!matches!(caller.work_turn(grant(),1,|cx|work.step(input,cx)).unwrap(),ArtifactCommandWorkStep::Complete(_)));}
  assert!(reached);caller.cancel().cancel_now();assert!(caller.work_turn(grant(),1,|cx|work.step(input,cx)).is_err());super::constituent_optional_shape_tests::close_with_denials(caller,work);assert!(work.terminal_is_empty());});caller.finish();
}
#[test]
fn original_list_guidance_keeps_cardinality_and_each_word_editable_without_defaults(){
 use semio_framework_plugin::action_staging::*;use semio_framework_plugin_decl_staged_form::*;
 type Guidance=super::super::super::type_guidance::IfcTypeInputSourceWork<DetailsTestProfile>;
 if DetailsTestProfile::catalog().schema!="IFC4X3_ADD2"{return;}
 let law=contract();for row in law["cases"].as_array().unwrap(){let snapshot=source(&law,row["entity"].as_str().unwrap());let editing::SnapshotEditEvent::SetValue{path,value}=event(row)else{unreachable!()};let mut donor=Some(StagedFormRequest{token:StagedFormToken{action:editing::SET_SNAPSHOT_VALUE_ACTION_ID.into(),window:"list-original".into(),generation:"1".into(),revision:"0".repeat(64)},locale:semio_framework_ui_locale::Locale::De,args:DslValue::Object(vec![("path".into(),DslValue::String(path)),("value".into(),value)]),page:None});let mut caller=OriginalWorkFixture::new();let mut guide=Some(Guidance::default());let mut output=None;
  assert!(caller.work_turn(grant(),1,|cx|guide.as_mut().unwrap().receive(&mut donor,&snapshot,[0;32],cx)).unwrap());for turn in 0..1000000{let demand=guide.as_ref().unwrap().demands().unwrap();for axis in 0..6{let mut denied=grant();let mut fuel=1;match axis{0=>denied.maximum_items=0,1 if demand.copy_bytes>0=>denied.maximum_copy_bytes=demand.copy_bytes-1,2 if demand.capacity_bytes>0=>denied.maximum_capacity_bytes=demand.capacity_bytes-1,3 if demand.release_bytes>0=>denied.maximum_release_bytes=demand.release_bytes-1,4=>denied.maximum_depth=0,5=>fuel=0,_=>continue};let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.work_turn(denied,fuel,|cx|{let before=cx.retained_progress();let answer=guide.as_mut().unwrap().advance(&snapshot,[0;32],cx);assert_eq!(before,cx.retained_progress());answer}));assert!(!answer.unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}if caller.work_turn(grant(),1,|cx|guide.as_mut().unwrap().advance(&snapshot,[0;32],cx)).unwrap(){break;}assert!(turn<999999);}
  assert!(caller.work_turn(grant(),1,|cx|guide.as_mut().unwrap().take(&mut output,cx)).unwrap());let prepared=output.as_ref().unwrap();assert_eq!(prepared.status().ready,row["admitted"].as_bool().unwrap());let words=row["words"].as_array().unwrap();assert_eq!(prepared.controls(),words.len()+1);let cardinality=prepared.control(0).unwrap();let StagedScalarKind::Choice{value,choices}=cardinality.scalar.kind else{panic!("explicit cardinality")};assert_eq!(value,words.len().to_string());assert!(choices.len()<=32);let StagedBodyBinding::Action(binding)=cardinality.binding.unwrap()else{panic!("cardinality binding")};let selected=DslValue::String(words.len().to_string());assert!(binding.plan(prepared.status(),Some(&selected)).is_ok());
  for(index,word)in words.iter().enumerate(){let control=prepared.control(index+1).unwrap();let StagedScalarKind::Text{value}=control.scalar.kind else{panic!("typed LIST word")};assert_eq!(value,word.as_str().unwrap());let StagedBodyBinding::Action(binding)=control.binding.unwrap()else{panic!("original LIST binding")};assert!(binding.edits.iter().any(|edit|matches!(edit,StagedFormBindingEdit::Text{path}if path.last().is_some_and(|part|part=="bits"))));}
  caller.cancel().cancel_now();super::type_guidance_request_tests::retire_owner(&mut caller,&mut output);super::type_guidance_request_tests::retire_owner(&mut caller,&mut guide);assert_eq!(Arc::strong_count(&snapshot),1);caller.finish();}
}
